      hu: ["Középkori kapu", "Vallási helyszín", "Kulturális örökség", "Zágrábi óváros"],
      ro: ["Poartă medievală", "Loc religios", "Moștenire culturală", "Orașul vechi Zagreb"],
      en: ["Medieval gate", "Religious site", "Cultural heritage", "Zagreb old town"],
